 std::printf("PASS: original silhouette/9-tap additive blur/multiplicative receiver, center=%08x outside=%08x, retained-VS=%s\n",center,outside,argc==2?"tested":"not requested");s->Release();b->Release();back->Release();readback->Release();silhouette->Release();blur->Release();d->Release();SDL_DestroyWindow(w);SDL_Quit();
